    final Uint8List? bytes = toUint8List(data);
    return bytes == null
        ? null
        : pigeon_CacheMessagesmessageCodec.decodeMessage(
            ByteData.sublistView(bytes),
          );
  }
}

Object? _convertNumberWrapperToDart(
  ffi_bridge.CacheMessagesNumberWrapper value,
) {
  switch (value.type) {
    case 1:
      return value.number.longValue;
    case 2:
      return value.number.doubleValue;
    case 3:
      return value.number.boolValue;
    case 4:
      return PigeonInternalWireCacheChecksumAlgorithmNativeInterop.fromNSNumber(
        value.number,
      );
    case 5:
      return PigeonInternalWireCacheEvictionPolicyNativeInterop.fromNSNumber(
        value.number,
      );
    case 6:
      return PigeonInternalWireCacheResultSourceNativeInterop.fromNSNumber(
        value.number,
      );
    case 7:
      return PigeonInternalWireCacheTransferStateNativeInterop.fromNSNumber(
        value.number,
      );
    default:
      throw ArgumentError.value(value);
  }
}

ffi_bridge.CacheMessagesNumberWrapper _convertToFfiNumberWrapper(Object value) {
  switch (value) {
    case int _:
      return ffi_bridge.CacheMessagesNumberWrapper.alloc().initWithNumber(
        NSNumber.alloc().initWithLong(value),
        type: 1,
      );
    case double _:
      return ffi_bridge.CacheMessagesNumberWrapper.alloc().initWithNumber(
        NSNumber.alloc().initWithDouble(value),
        type: 2,
      );
    case bool _:
      return ffi_bridge.CacheMessagesNumberWrapper.alloc().initWithNumber(
        NSNumber.alloc().initWithLong(value ? 1 : 0),
        type: 3,
      );
    case WireCacheChecksumAlgorithm _:
      return ffi_bridge.CacheMessagesNumberWrapper.alloc().initWithNumber(
        value.toNSNumber(),
        type: 4,
      );
    case WireCacheEvictionPolicy _:
      return ffi_bridge.CacheMessagesNumberWrapper.alloc().initWithNumber(
        value.toNSNumber(),
        type: 5,
      );
    case WireCacheResultSource _:
      return ffi_bridge.CacheMessagesNumberWrapper.alloc().initWithNumber(
        value.toNSNumber(),
        type: 6,
      );
    case WireCacheTransferState _:
      return ffi_bridge.CacheMessagesNumberWrapper.alloc().initWithNumber(
        value.toNSNumber(),
        type: 7,
      );
    default:
      throw ArgumentError.value(value);
  }
}

bool _isType<T>(Type t) => T == t;
bool _isTypeOrNullableType<T>(Type t) => _isType<T>(t) || _isType<T?>(t);

void _throwNoInstanceError(String channelName) {
  String nameString = 'named $channelName';
  if (channelName == defaultInstanceName) {
    nameString = 'with no name';
  }
  final String error = 'No instance $nameString has been registered.';
  throw ArgumentError(error);
}

/// Native engine key meaning "no engine", matching `Long.MIN_VALUE` in Kotlin
/// and `Int64.min` in Swift.
const int _pigeonNoEngineKey = -9223372036854775808;

/// The native engine key this isolate has been associated with, learned from
/// the first native instance it resolves.
///
/// Used to route lookups when [PlatformDispatcher.instance.engineId] is
/// unavailable or native code registered with a synthetic key.
int? _pigeonEngineAffinity;

/// Updates Flutter API registrations made before [_pigeonEngineAffinity]
/// was known.
void _pigeonUpdateFlutterApiEngineAffinity() {
  _CacheProgressFlutterApiRegistrar.pigeonVar_updateEngineAffinity();
}

void _throwIfFfiError(ffi_bridge.PigeonError error) {
  if (error.code != null) {
    throw _wrapFfiError(error);
  }
}

PlatformException _wrapFfiError(ffi_bridge.PigeonError error) =>
    PlatformException(
      code: error.code!.toDartString(),
      message: error.message?.toDartString(),
      details: NSString.isA(error.details)
          ? error.details!.toDartString()
          : error.details,
    );

void _reportFfiError(ffi_bridge.PigeonError errorOut, Object e) {
  if (e is PlatformException) {
    errorOut.code = NSString(e.code);
    errorOut.message = NSString(e.message ?? '');
    errorOut.details = NSString((e.details ?? '').toString());
  } else {
    errorOut.code = NSString('error');
    errorOut.message = NSString(e.toString());
    errorOut.details = null;
  }
}

PlatformException _wrapJniException(JThrowable e) {
  if (e.isA<jni_bridge.FlutterError>(jni_bridge.FlutterError.type)) {
    final jni_bridge.FlutterError pigeonError = e.as(
      jni_bridge.FlutterError.type,
    );
    return PlatformException(
      code: pigeonError.code.toDartString(),
      message: pigeonError.message?.toDartString(),
      details: _PigeonJniBuffers.decode(pigeonError.details as JByteArray?),
      stacktrace: e.javaStackTrace,
    );
  }
  return PlatformException(
    code: 'PlatformException',
    message: e.message,
    details: e,
    stacktrace: e.javaStackTrace,
  );
}

